<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --bg:#FAFAFA;--bg-white:#FFFFFF;--text:#171717;--text-secondary:#525252;
  --text-muted:#737373;--accent:#0072F5;--accent-hover:#005BC4;
  --border:#E5E5E5;--border-light:#F0F0F0;--shadow:0 1px 3px rgba(0,0,0,.06);
  --shadow-md:0 4px 12px rgba(0,0,0,.08);--shadow-lg:0 8px 24px rgba(0,0,0,.12);
