html{font-size:16px;scroll-behavior:smooth}
body{font-family:var(--font);color:var(--text);background:var(--bg);line-height:1.6;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:none;background:none}
img{display:block;max-width:100%}

/* ─── Header ─── */
.header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.85);backdrop-filter:blur(12px);border-bottom:1px solid var(--border)}
.header-inner{max-width:var(--max-w);margin:0 auto;padding:0 24px;display:flex;align-items:center;height:64px;gap:8px}
.logo{font-size:18px;font-weight:700;letter-spacing:-.02em;display:flex;align-items:center;gap:8px;white-space:nowrap}
.logo svg{flex-shrink:0}
.logo .sep{color:var(--border);font-weight:300;margin:0 4px}
.logo .blog-label{color:var(--text-muted);font-weight:500}
.nav-main{display:flex;align-items:center;gap:4px;margin-left:24px}
.nav-item{position:relative;padding:8px 12px;font-size:14px;font-weight:500;color:var(--text-secondary);border-radius:var(--radius);transition:color .15s,background .15s}
.nav-item:hover{color:var(--text);background:rgba(0,0,0,.04)}
.nav-item svg{margin-left:4px;vertical-align:middle;transition:transform .2s}
.nav-item[aria-expanded="true"] svg{transform:rotate(180deg)}
.nav-right{display:flex;align-items:center;gap:8px;margin-left:auto}
.btn-ghost{padding:8px 14px;font-size:14px;font-weight:500;color:var(--text-secondary);border-radius:var(--radius);transition:all .15s}
.btn-ghost:hover{color:var(--text);background:rgba(0,0,0,.04)}
.btn-primary{padding:8px 16px;font-size:14px;font-weight:600;color:#fff;background:var(--text);border-radius:var(--radius);transition:background .15s}
.btn-primary:hover{background:#333}
.btn-accent{padding:8px 16px;font-size:14px;font-weight:600;color:#fff;background:var(--accent);border-radius:var(--radius);transition:background .15s}
.btn-accent:hover{background:var(--accent-hover)}

/* ─── Mega Menu ─── */
.mega-menu{position:absolute;top:calc(100% + 1px);left:50%;transform:translateX(-50%);background:var(--bg-white);border:1px solid var(--border);border-radius:var(--radius-lg);box-shadow:var(--shadow-lg);padding:24px 28px;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .2s,visibility .2s;min-width:520px}
.mega-menu.show{opacity:1;visibility:visible;pointer-events:auto}
.mega-cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:24px}
.mega-col h4{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--text-muted);margin-bottom:12px}
.mega-col a{display:block;padding:6px 0;font-size:13.5px;font-weight:500;color:var(--text);transition:color .15s}
.mega-col a:hover{color:var(--accent)}
.mega-col .sub{display:block;font-size:12px;font-weight:400;color:var(--text-muted);margin-top:1px}

/* ─── Mobile menu ─── */
