}

/* ─── Hero / Blog title ─── */
.blog-hero{max-width:var(--max-w);margin:0 auto;padding:48px 24px 0}
.blog-hero h1{font-size:clamp(32px,5vw,48px);font-weight:800;letter-spacing:-.03em;line-height:1.1;color:var(--text)}

/* ─── Category Filters ─── */
.filters-bar{max-width:var(--max-w);margin:0 auto;padding:24px 24px 0;display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.pill{padding:7px 16px;font-size:13.5px;font-weight:500;border-radius:var(--radius-pill);border:1px solid var(--border);color:var(--text-secondary);background:var(--bg-white);transition:all .18s;white-space:nowrap}
.pill:hover{border-color:var(--text);color:var(--text)}
.pill.active{background:var(--text);color:#fff;border-color:var(--text)}
