.search-input{padding:8px 14px 8px 36px;font-size:14px;border:1px solid var(--border);border-radius:var(--radius-pill);background:var(--bg-white);width:220px;transition:border-color .15s,width .2s;font-family:var(--font);color:var(--text)}
