.featured-card .card-body{padding:20px 24px}
.featured-card .card-meta{font-size:13px;color:var(--text-muted);margin-bottom:8px;display:flex;align-items:center;gap:8px}
.featured-card .card-title{font-size:20px;font-weight:700;letter-spacing:-.02em;line-height:1.3;margin-bottom:8px}
.featured-card.large .card-title{font-size:24px}
.featured-card .card-excerpt{font-size:14px;color:var(--text-secondary);line-height:1.6;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
