.btn-white{padding:10px 20px;font-size:14px;font-weight:600;color:var(--text);background:#fff;border-radius:var(--radius);transition:background .15s}
.btn-white:hover{background:#f0f0f0}
.btn-outline-white{padding:10px 20px;font-size:14px;font-weight:600;color:#fff;background:transparent;border:1px solid rgba(255,255,255,.3);border-radius:var(--radius);transition:all .15s}
.btn-outline-white:hover{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.5)}

/* ─── Footer ─── */
.footer{background:var(--text);color:rgba(255,255,255,.7);padding:64px 0 32px}
.footer-inner{max-width:var(--max-w);margin:0 auto;padding:0 24px}
