let openMenu = null;
function toggleMega(name) {
  const menu = document.getElementById('mega-' + name);
  const btn = document.getElementById('nav-' + name);
  if (openMenu && openMenu !== name) {
    document.getElementById('mega-' + openMenu).classList.remove('show');
    document.getElementById('nav-' + openMenu).setAttribute('aria-expanded', 'false');
  }
  const isOpen = menu.classList.toggle('show');
  btn.setAttribute('aria-expanded', isOpen);
  openMenu = isOpen ? name : null;
}

document.addEventListener('click', (e) => {
